/// One entry of MTLLinkedFunctions.groups (an NSDictionary): a callsite group name and its functions.
#[derive(Clone, Debug, PartialEq)]
pub struct LinkedFunctionGroup {
    /// wire type `str`.
    pub name: String,
    /// wire type `[Function]`.
    pub functions: Vec<Handle>,
}

impl LinkedFunctionGroup {
    fn encode_fields(&self, w: &mut Writer<'_>) -> Result<(), EncodeError> {
        w.str(&self.name, "name")?;
        w.count(self.functions.len(), "functions")?;
        for &e in &self.functions {
            w.handle(e);
        }
        Ok(())
    }

    fn decode_fields(r: &mut Reader<'_>) -> Result<Self, DecodeError> {
        let name = r.str("name")?;
        let functions = { let n = r.count("functions")?; let mut v = Vec::with_capacity(n); for _ in 0..n { v.push(r.handle("functions")?); } v };
        let v = LinkedFunctionGroup { name, functions };
        Ok(v)
    }

    /// A random value, drawn in the same order as the C++ generator in WebMetalWireFuzz.h.
    pub fn random(rng: &mut Rng) -> Self {
        let name = { let n = rng.string_len(); rng.string(n) };
        let functions = { let n = rng.array_len(); let mut v = Vec::with_capacity(n as usize); for _ in 0..n { v.push(rng.handle()); } v };
        LinkedFunctionGroup { name, functions }
    }
}

