    /// Decode every record of `bytes` in order.
    pub fn decode_all(bytes: &[u8]) -> Result<Vec<(usize, Command)>, DecodeError> {
        let mut out = Vec::new();
        let mut at = 0;
        while at < bytes.len() {
            let (v, len) = Command::decode(&bytes[at..], at)?;
            out.push((at, v));
            at += len;
        }
        Ok(out)
    }

