/// An event record.
#[derive(Clone, Debug, PartialEq)]
pub enum Event {
    CommandBufferScheduled(CommandBufferScheduled),
    CommandBufferCompleted(CommandBufferCompleted),
    EncoderCompleted(EncoderCompleted),
    SharedEventListener(SharedEventListener),
    DeviceLost(DeviceLost),
}

impl Event {
    /// The record's opcode.
    pub fn opcode(&self) -> u16 {
        match self {
            Event::CommandBufferScheduled(_) => 0x7001,
            Event::CommandBufferCompleted(_) => 0x7002,
            Event::EncoderCompleted(_) => 0x7005,
            Event::SharedEventListener(_) => 0x7003,
            Event::DeviceLost(_) => 0x7004,
        }
    }

    /// Append the record to `out`, whose length must be a multiple of 8.
    pub fn encode(&self, out: &mut Vec<u8>) -> Result<(), EncodeError> {
        let start = out.len();
        let mut w = Writer::begin(out, self.opcode());
        let r = match self {
            Event::CommandBufferScheduled(v) => v.encode_fields(&mut w),
            Event::CommandBufferCompleted(v) => v.encode_fields(&mut w),
            Event::EncoderCompleted(v) => v.encode_fields(&mut w),
            Event::SharedEventListener(v) => v.encode_fields(&mut w),
            Event::DeviceLost(v) => v.encode_fields(&mut w),
        };
        match r {
            Ok(()) => w.finish(),
            Err(e) => {
                drop(w);
                out.truncate(start);
                Err(e)
            }
        }
    }

    /// Decode the record at the start of `bytes` (stream offset `base`); returns it and its length.
    pub fn decode(bytes: &[u8], base: usize) -> Result<(Event, usize), DecodeError> {
        let (opcode, record) = split_record(bytes, base)?;
        let mut r = Reader::new(record, base);
        let v = match opcode {
            0x7001 => Event::CommandBufferScheduled(CommandBufferScheduled::decode_fields(&mut r)?),
            0x7002 => Event::CommandBufferCompleted(CommandBufferCompleted::decode_fields(&mut r)?),
            0x7005 => Event::EncoderCompleted(EncoderCompleted::decode_fields(&mut r)?),
            0x7003 => Event::SharedEventListener(SharedEventListener::decode_fields(&mut r)?),
            0x7004 => Event::DeviceLost(DeviceLost::decode_fields(&mut r)?),
            _ => return Err(DecodeError { offset: base, kind: unknown_or_wrong_channel(opcode) }),
        };
        r.finish()?;
        Ok((v, record.len()))
    }

    /// Decode every record of `bytes` in order.
    pub fn decode_all(bytes: &[u8]) -> Result<Vec<(usize, Event)>, DecodeError> {
        let mut out = Vec::new();
        let mut at = 0;
        while at < bytes.len() {
            let (v, len) = Event::decode(&bytes[at..], at)?;
            out.push((at, v));
            at += len;
        }
        Ok(out)
    }

    /// A random record of this channel (the op chosen uniformly in schema order).
    pub fn random(rng: &mut Rng) -> Event {
        match rng.below(5) {
            0 => Event::CommandBufferScheduled(CommandBufferScheduled::random(rng)),
            1 => Event::CommandBufferCompleted(CommandBufferCompleted::random(rng)),
            2 => Event::EncoderCompleted(EncoderCompleted::random(rng)),
            3 => Event::SharedEventListener(SharedEventListener::random(rng)),
            4 => Event::DeviceLost(DeviceLost::random(rng)),
            _ => unreachable!(),
        }
    }
}

