fn encode_outcome<T>(w: &mut Writer<'_>, v: &Result<T, Failure>, f: fn(&T, &mut Writer<'_>) -> Result<(), EncodeError>) -> Result<(), EncodeError> {
    match v {
        Ok(body) => {
            w.u32(0);
            f(body, w)
        }
        Err(failure) => {
            if failure.status == 0 {
                return Err(EncodeError::BadFailure);
            }
            failure.encode_fields(w)
        }
    }
}

fn decode_outcome<T>(r: &mut Reader<'_>, f: fn(&mut Reader<'_>) -> Result<T, DecodeError>) -> Result<Result<T, Failure>, DecodeError> {
    let start = r.position();
    if r.u32()? == 0 {
        return Ok(Ok(f(r)?));
    }
    r.set_position(start);
    Ok(Err(Failure::decode_fields(r)?))
}

fn unknown_or_wrong_channel(opcode: u16) -> DecodeErrorKind {
    if opcode & REPLY_BIT != 0 || op_info(opcode).is_some() {
        DecodeErrorKind::WrongChannel(opcode)
    } else {
        DecodeErrorKind::UnknownOpcode(opcode)
    }
}

/// Which direction and framing a record uses.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum Channel {
    /// Guest to host, one reply each.
    Control,
    /// Guest to host inside a command buffer's stream.
    Stream,
    /// Host to guest, collected with FetchEvents.
    Event,
}

/// Static description of an op, for diagnostics (an unimplemented opcode is reported with its Metal methods).
#[derive(Clone, Copy, Debug)]
pub struct OpInfo {
    pub opcode: u16,
    pub name: &'static str,
    pub channel: Channel,
    /// "Protocol selector" pairs this record carries.
    pub methods: &'static [&'static str],
}

